E.append((8454, 8509, 'Vue.js 是一套用于构建用户界面的渐进式 JavaScript 框架，采用数据双向绑定与组件化开发思想，核心库只关注视图层，学习成本较低且易于与第三方库或既有项目整合。Vue.js 具备响应式数据绑定、虚拟 DOM 与组件化三大特性：数据变化时视图自动更新，减少开发者手动操作 DOM 的工作量；虚拟 DOM 通过差异比对降低渲染开销；组件化则把页面拆分为可复用的独立单元，便于多人协作与后期维护。Vue.js 拥有丰富的生态系统，Vue Router 负责前端路由与页面跳转，Pinia 负责全局状态管理，Element Plus 提供成套的企业级 UI 组件，ECharts 则用于图表的绘制与交互。在本项目中，管理端与匠人端均基于 Vue 3.4 开发，配合 Vite 5 完成构建与热更新，通过 Vue Router 的路由守卫实现三端页面的访问权限控制，借助 Pinia 保存用户登录态与角色信息，使前后端分离架构下的页面交互更加流畅，管理界面的表格、表单、图表等高级功能也得到良好支持。'))
E.append((8382, 8446, 'Spring Boot 是在 Spring 框架基础上发展起来的快速开发脚手架，遵循“约定优于配置”的设计理念，通过自动装配机制大幅减少传统 Spring 项目中大量的 XML 配置工作。它内置了 Tomcat 等 Servlet 容器，可将应用打包为可执行 JAR 直接运行，无需额外部署 Web 容器。Spring Boot 还提供了统一管理的起步依赖（Starter），把常用功能封装为开箱即用的模块，并通过 Actuator 暴露健康检查与运行指标。其核心优势在于简化配置、快速集成、易于测试以及良好的生态兼容性。在本系统中，后端以 Spring Boot 3.2.5 为核心构建分层架构，Controller 层负责接收 HTTP 请求与参数校验，Service 层承载业务逻辑，Mapper 层通过 MyBatis-Plus 访问数据库；同时依托 Spring 的依赖注入与声明式事务能力保证业务一致性，借助拦截器统一完成 JWT 登录校验与接口限流，通过 AOP 切面实现操作日志的自动采集，并以 RESTful 风格接口为前端提供数据服务。正是依靠 Spring Boot 高效的开发能力与稳定的运行时表现，系统才能在持续迭代中保持稳定运行。'))
E.append((8244, 8369, '微信小程序是由腾讯公司推出的一种不需要下载安装即可使用的轻量级应用形态，运行在微信客户端内部，用户通过扫码或搜索即可直接打开，具备“即用即走”的特点。小程序采用 WXML 描述结构、WXSS 负责样式、JavaScript 处理逻辑，并提供丰富的原生组件与开放接口，可与后端服务通过 HTTPS 通信。虽然本系统的用户端最终以浏览器访问的响应式 Web 页面实现，但小程序所代表的轻量级、免安装、跨平台的设计理念对系统产生了重要影响：用户端页面采用移动优先的响应式布局，在手机与桌面浏览器上均可正常使用，配合图片懒加载与资源压缩降低首屏耗时，使公众无需安装任何客户端即可便捷地浏览非遗作品、购买手工艺品与预约线下体验课程。'))
E.append((8041, 8230, '本毕业设计主要研究基于 SpringBoot 与 Vue 的非遗手工艺品展示与预约体验平台的设计与实现，重点解决非遗作品展示形式单一、线上售卖与线下体验渠道割裂、体验课名额管理混乱等实际问题。在系统设计阶段，通过分析不同用户角色的使用场景与功能诉求，将系统划分为普通用户、非遗匠人、平台管理员三类角色，并据此设计用户端、匠人端、管理员端三个子系统：用户端侧重作品浏览、商品购买与体验课程预约等基础功能，匠人端侧重作品商品维护、预约审核与现场核销等经营功能，管理端则侧重资质审核、预约监管、规则配置与数据统计分析等运营功能。在功能实现上，完整开发了用户管理、作品展示、商品交易、体验预约、评价互动、运营管理六大功能模块，并通过功能测试、接口测试、并发压测与兼容性测试等多种方法确保系统稳定性。研究目标是构建一个高效便捷的非遗展示与预约体验平台，提升非遗文化的传播效率与匠人的线上增收能力，优化公众了解与参与非遗的体验。'))
E.append((7737, 8035, '本课题综合采用文献资料研究法、需求分析法、原型设计法、系统开发法、测试验证法与对比实验法开展研究。首先采用文献资料研究法，查阅非遗保护政策文件以及国内外非遗数字化、手工艺电商、前后端分离架构相关文献，明确系统的功能边界与技术路线。其次采用需求分析法，通过访谈非遗匠人与目标用户、分析同类平台的优缺点，明确功能需求与非功能需求，形成用例模型与模块划分方案，确保系统功能契合目标用户的使用场景。然后采用原型设计法，绘制核心页面原型，确定信息布局与交互流程，减少后期返工。在开发阶段采用系统开发法，按照软件工程的思想完成系统总体架构、功能模块的设计与前后端的编码实现，后端基于 SpringBoot 分层架构提供 RESTful 接口，前端基于 Vue 3 与 Element Plus 实现页面渲染，并以敏捷开发模式确保设计的灵活性与迭代改进能力。在验证阶段采用系统测试法与对比实验法，通过 JUnit 单元测试、Postman 接口测试、JMeter 并发压力测试以及多浏览器兼容性测试全面检验系统的正确性、性能与稳定性，并针对预约名额并发控制、热点数据缓存等关键场景对比多种实现方案的一致性与性能差异，择优落地，最后依据测试结果持续优化系统功能与交互体验。'))
E.append((7593, 7723, '综观国内外已有研究与实践，可发现国外系统开发大多偏向数据分析与数字化记录标准，而国内系统更多关注操作的便捷性、平台化交易与线下活动的组织效率。两者的共同点在于都重视移动端体验与数据支撑，但对非遗领域“线上售卖与线下体验预约深度融合”的一体化平台关注不足。总结现有研究的经验与不足，对未来系统需要具备的功能开展分析，才能更好地满足非遗数字化传承与活化利用的实际所需。因此，构建一个融合作品展示、手工商城、匠人主页与体验课程预约的一体化平台，具有重要的研究价值与实践意义。'))
E.append((7362, 7592, '在国外，联合国教科文组织自 2003 年通过《保护非物质文化遗产公约》以来，持续推动各缔约国建立非遗数字化档案，欧美日韩等国家和地区在非遗数字化记录、虚拟展陈与手工艺电商方面积累了较多经验。在电商领域，Etsy、Amazon Handmade 等平台已形成较为成熟的手工艺品交易生态，通过店铺体系、评价机制与个性化推荐连接全球手工艺者与消费者；在个性化推荐方面，协同过滤与矩阵分解等技术被广泛应用于手工艺品等长尾商品的推荐场景。相关研究多围绕文化遗产元数据模型、数字资源组织以及平台化交易机制展开，为非遗资源的结构化描述与线上交易提供了理论支撑。总体来看，国外研究偏重数字化记录标准与平台化交易机制，较少涉及时段性线下体验预约与线上售卖深度融合的一体化平台设计。'))
E.append((7021, 7361, '在国内，国家层面先后出台《中华人民共和国非物质文化遗产法》以及中共中央办公厅、国务院办公厅《关于进一步加强非物质文化遗产保护工作的意见》，明确提出推动非遗与互联网、电子商务、文化旅游融合发展。实践层面，淘宝、京东等综合电商平台开设非遗频道，故宫文创与各类非遗工坊通过直播、短视频带动销售；部分省市搭建了非遗门户网站与数字博物馆，实现了作品展示与资讯发布。学术层面，刘魁立、张勃等学者从非遗保护理论与传承机制角度开展了系统研究，也有研究者围绕非遗数字化传播路径、手工艺电商平台运营模式进行探讨。相关研究与实践表明，数字化与平台化已成为非遗保护与活化利用的重要途径，“基于互联网平台的非遗展示与推广”在提升传播效率、拓宽销售渠道方面确实具有重要的应用价值，这为本课题的开展提供了充分的现实依据。'))
E.append((6979, 7012, '开发一个集作品展示、手工商城、匠人主页与体验课程在线预约于一体的非遗手工艺品展示与预约体验平台，既能帮助公众便捷地了解、购买与体验非遗，也能让匠人低成本地自主运营线上店铺与线下体验业务，同时为平台管理者提供高效的内容审核、预约监管与数据分析手段，具有明确的应用价值与现实意义。'))
E.append((6913, 6978, '非物质文化遗产是中华民族在长期生产生活实践中创造并世代相传的文化瑰宝，承载着民族的思维方式、审美情趣与工艺智慧。然而随着现代化进程加快，部分非遗技艺面临传承人老龄化、市场认知度低、产品销售渠道单一等现实困境，传统的线下门店与展会销售模式客群半径有限，非遗展示与体验的组织也多依赖微信群或电话沟通，信息分散、名额管理混乱、数据难以沉淀，公众了解、购买与体验非遗的需求难以得到有效满足。因此，借助数字技术为非遗开辟新的传播与变现路径，建设一个信息化、规范化的展示与预约体验平台，已成为文化保护与产业发展共同关注的问题。'))
E.append((6869, 6902, '开发一个集作品展示、手工商城、匠人主页与体验课程在线预约于一体的非遗手工艺品展示与预约体验平台，既能拓宽非遗作品的线上销路、把“旁观式”的文化消费转化为“参与式”的体验消费，也能让管理者高效地完成内容审核、预约监管与数据统计，从而更好地满足非遗展示与预约体验管理的高效化、信息化需求。'))
E.append((6803, 6868, '非物质文化遗产是中华民族的文化瑰宝，但部分非遗技艺面临传承人老龄化、展示渠道单一、产品销售依赖线下门店和展会等困境。传统模式下，非遗作品多以图文介绍的形式零散展示，缺少完整的商品规格、库存、订单与售后能力；线下体验课的报名多依赖微信群或电话，名额管理混乱且缺少审核与通知机制；匠人的主体地位不突出，其师承、履历与代表作难以系统呈现；同时平台的浏览量、销量、预约热度等运营数据也难以被有效采集与利用，导致数据价值挖掘不足。公众了解、购买与体验非遗的需求，与非遗资源的数字化、平台化供给之间仍存在明显差距。'))

